sys_script_include.script:
(function transform(transformBuilder, transformScriptArgs) {
    try {
        if (!transformBuilder) return;

        var listModel = transformBuilder

        // do not remove
        .transform();

        // Only Quarter column should be editable
        var editableColumn = 'quarter'; // replace with actual field name if needed

        listModel.columnDefinitions.columns.forEach(function(column) {
            if (column.key === editableColumn) {
                column.editable = true;
                column.readOnly = false;
            } else {
                column.editable = false;
                column.readOnly = true;
            }
        });

        listModel.rowDefinitions.rows.forEach(function(row) {
            Object.keys(row.cells).forEach(function(cellKey) {
                var cell = row.cells[cellKey];

                if (cellKey === editableColumn) {
                    cell.editable = true;
                    cell.readOnly = false;
                    cell.disabled = false;
                } else {
                    cell.editable = false;
                    cell.readOnly = true;
                    cell.disabled = true;
                }
            });
        });

        return listModel;
    }

    catch (error) {
        return {
            failed: true,
            error: error.message
        };
    }
})(transformBuilder, transformScriptArgs);
